import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin } from './helpers';

// [Verifier] NOTE: duel state is shared across every test/spec file in this
// run (single persistent room), so every test here first waits out any
// lingering active duel (bounded by the longest offered duration, 90s)
// before starting its own with the shortest duration (30s).
const MAX_LINGERING_DUEL_WAIT_MS = 100_000;

test.describe(`player: see the results of a finished duel — winner, everyone's score, and when it happened`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a duel's timer elapses, the duels screen shows every participant's score, a winner badge for the highest score, and a timestamp, visible to all room members`, async ({ browser }) => {
    test.setTimeout(150_000);
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    await pageA.getByTestId('tab-duels').click();
    await pageB.getByTestId('tab-duels').click();

    await expect(pageA.getByTestId('duel-countdown')).toBeHidden({ timeout: MAX_LINGERING_DUEL_WAIT_MS });
    await pageA.getByTestId('field-duration_seconds').selectOption('30');
    await pageA.getByTestId('action-start_duel').click();
    await expect(pageB.getByTestId('duel-countdown')).toBeVisible({ timeout: 5_000 });

    // Both room members' clients submit their own result once the fixed
    // timer elapses, and the shared duel flips to finished for everyone.
    await expect(pageB.getByTestId('duel-countdown')).toBeHidden({ timeout: 45_000 });

    // [Verifier] NOTE: duels render in the order `get_duels()` returns them
    // (insertion order), so the most recently finished one is last.
    const duelCard = pageB.getByTestId('item-duel').last();
    await expect(duelCard.getByText('finished')).toBeVisible();
    await expect(duelCard.getByTestId('item-duel_result')).toHaveCount(2, { timeout: 10_000 });
    await expect(duelCard.getByText('🏆 winner').first()).toBeVisible();
    // [Verifier] NOTE: no testid on the ended-at timestamp; it's the last
    // span in the card's meta row (duration is the other one).
    await expect(duelCard.locator('.meta span').last()).toBeVisible();

    await ctxA.close();
    await ctxB.close();
  });

  test(`past duel results remain visible after new duels are played`, async ({ page }) => {
    test.setTimeout(150_000);
    await createWorkspace(page);
    await page.getByTestId('tab-duels').click();

    await expect(page.getByTestId('duel-countdown')).toBeHidden({ timeout: MAX_LINGERING_DUEL_WAIT_MS });
    const before = await page.getByTestId('item-duel').count();

    // Play a duel to completion. The "no active duel" control (select +
    // start button) shares the same `active` flag as the countdown, but it
    // only remounts once this client's own refresh() (self-authored
    // finish_duel -> refetch) has round-tripped -- give it explicit
    // headroom beyond the default 15s action timeout instead of relying on
    // selectOption's implicit auto-wait, since back-to-back duels leave very
    // little slack for that refresh to land.
    await expect(page.getByTestId('field-duration_seconds')).toBeVisible({ timeout: 30_000 });
    await page.getByTestId('field-duration_seconds').selectOption('30');
    await page.getByTestId('action-start_duel').click();
    await expect(page.getByTestId('duel-countdown')).toBeHidden({ timeout: 45_000 });
    await expect(page.getByTestId('item-duel')).toHaveCount(before + 1, { timeout: 10_000 });

    // Play a second duel -- the first one's card must still be present.
    await expect(page.getByTestId('field-duration_seconds')).toBeVisible({ timeout: 30_000 });
    await page.getByTestId('field-duration_seconds').selectOption('30');
    await page.getByTestId('action-start_duel').click();
    await expect(page.getByTestId('duel-countdown')).toBeHidden({ timeout: 45_000 });
    await expect(page.getByTestId('item-duel')).toHaveCount(before + 2, { timeout: 10_000 });
  });
});
